pub trait View { fn update(&mut self, model: &Model); fn close(&mut self); }
pub struct Handler { views: HashMap<ViewId, Box<dyn View>>, next: u64 }
impl Handler {
    pub fn open(&mut self, make: fn(&Model) -> Box<dyn View>, m: &Model) -> ViewId {
        self.next += 1; let id = ViewId(self.next);
        self.views.insert(id, make(m));            // create + register
        id                                         // handle, not the view
    }
    pub fn close(&mut self, id: ViewId) { if let Some(mut v) = self.views.remove(&id) { v.close() } }
    pub fn notify(&mut self, m: &Model) {
        let ids: Vec<ViewId> = self.views.keys().copied().collect();  // no borrow held
        for id in ids { if let Some(v) = self.views.get_mut(&id) { v.update(m); } }
    }
}

