struct App { screen: Screen, model: Model, outline_open: bool }   // the whole handler

impl eframe::App for App {
    fn update(&mut self, ctx: &egui::Context, _: &mut eframe::Frame) {
        egui::SidePanel::left("outline").show(ctx, |ui| self.show_outline(ui));
        egui::CentralPanel::default().show(ctx, |ui| match self.screen {
            Screen::Chart => self.show_chart(ui),     // a view = function of state
            Screen::Table => self.show_table(ui),
        });
    }
}
